def is_simple_power(x, n):
    """
    Return True if x is a simple power of n, i.e. x == n**k for some
    non-negative integer k, and False otherwise.
    """
    if x == 0:
        return n == 0

    if x == 1:
        return True

    if n == 1:
        return False

    if n == -1:
        return x == -1

    if n == 0:
        return False

    while x != 1:
        if x % n != 0:
            return False
        x //= n

    return True
