import re


def valid_date(date):
    """
    Validate a date string in the format mm-dd-yyyy.

    Returns True if the date is valid according to the given rules,
    otherwise returns False.
    """
    if not isinstance(date, str) or not date:
        return False

    if not re.fullmatch(r"[0-9]{2}-[0-9]{2}-[0-9]{4}", date):
        return False

    month_str, day_str, _ = date.split("-")
    month = int(month_str)
    day = int(day_str)

    if month < 1 or month > 12:
        return False

    if day < 1:
        return False

    if month in (1, 3, 5, 7, 8, 10, 12):
        if day > 31:
            return False
    elif month in (4, 6, 9, 11):
        if day > 30:
            return False
    else:  # month == 2
        if day > 29:
            return False

    return True


if __name__ == "__main__":
    assert valid_date("03-11-2000") is True
    assert valid_date("15-01-2012") is False
    assert valid_date("04-0-2040") is False
    assert valid_date("06-04-2020") is True
    assert valid_date("06/04/2020") is False
